{
  "summary": "Gather current Acme Cloud Services contract terms, SLA performance history, and any outstanding credits owed, then draft a renewal response addressing the proposed 12% increase.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract (pricing, term end date 31 Oct 2026, renewal clauses, currency), read any internal pricing/renewal policy documents, check SLA performance records against contractual SLAs using the 'SLA credit calculator' to determine any credits owed to us, and if any amounts are in a foreign currency (e.g., USD), use 'Currency converter (live)' to convert to our reporting currency.",
      "why": "The executor needs the exact contract terms, current pricing, SLA compliance/credit facts, and currency-converted figures to draft an accurate, fact-based renewal response."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft the reply to Acme Cloud Services addressing the contract renewal request, referencing the current contract terms, evaluating the proposed 12% price increase against our policy and SLA performance, noting any SLA credits owed to us, and proposing final terms or a counter-offer for human review.",
      "why": "The executor synthesizes all retrieved facts into a clear, complete vendor-facing response ready for human approval."
    }
  ],
  "escalate": null
}
